}"},{"rank":3,"score":31.3677,"file_path":"internal/scan/kubeconform.go","start_line":115,"end_line":141,"focus_line":137,"snippet_start_line":115,"snippet_end_line":141,"symbol_start_line":115,"symbol_end_line":141,"language":"Go","kind":"function","symbol_id":"local/devdesk:Go:internal/scan/kubeconform.go:function:RunKubeconform","symbol_name":"RunKubeconform","qualified_name":"RunKubeconform","signature":"func RunKubeconform(ctx context.Context, target string, tool ToolSpec, opts KubeconformOptions, progressFn func(string)) (*KubeconformReport, error)","signals":["body","symbol-usage","complete-symbol"],"snippet":"func RunKubeconform(ctx context.Context, target string, tool ToolSpec, opts KubeconformOptions, progressFn func(string)) (*KubeconformReport, error) {
	layout, err := k8s.Discover(target)
	if err != nil {
		return nil, fmt.Errorf("listing manifests: %w", err)
	}
	if opts.CacheDir != "" {
		if err := os.MkdirAll(opts.CacheDir, 0o755); err != nil {
			// Validation still works without a cache; it downloads each time.
			opts.CacheDir = ""
		}
	}
	v := &k8sValidation{target: target, kubeconform: tool, opts: opts,
		report: &KubeconformReport{Validated: len(layout.Manifests)}}

	if len(layout.Manifests) > 0 {
		if err := v.validateFiles(ctx, layout.Manifests, progressFn); err != nil {
			return nil, err
		}
	}
	if err := v.renderCharts(ctx, layout.Charts); err != nil {
		return nil, err
	}
	if err := v.renderKustomizations(ctx, layout.Kustomizations); err != nil {
		return nil, err
